void HandlerAsyncWaiter::IsAttributionReportingEnabled(
    bool* out_enabled, bool* out_debug_mode, ::network::mojom::AttributionSupport* out_attribution_support) {
  base::RunLoop loop;
  proxy_->IsAttributionReportingEnabled(
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_enabled
,
             bool* out_debug_mode
,
             ::network::mojom::AttributionSupport* out_attribution_support
,
             bool enabled,
             bool debug_mode,
             ::network::mojom::AttributionSupport attribution_support) {*out_enabled = std::move(enabled);*out_debug_mode = std::move(debug_mode);*out_attribution_support = std::move(attribution_support);
            loop->Quit();
          },
          &loop,
          out_enabled,
          out_debug_mode,
          out_attribution_support));
  loop.Run();
}



void HandlerAsyncWaiter::GetActiveSources(
    std::vector<WebUISourcePtr>* out_sources) {
  base::RunLoop loop;
  proxy_->GetActiveSources(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<WebUISourcePtr>* out_sources
,
             std::vector<WebUISourcePtr> sources) {*out_sources = std::move(sources);
            loop->Quit();
          },
          &loop,
          out_sources));
  loop.Run();
}

